// 5. CHART SPECIFICATIONS
// ==================================================

// CHART 1: national heatmap.

const chart1 = vl({
    width: 400,
    height: 240,
    data: { values: nationalData },

    encoding: {
        x: {
            field: "domain", type: "nominal", title: null,
            sort: ["Reading", "Numeracy"],
            axis: { labelAngle: 0 }
        },
        y: {
            field: "gradeLabel", type: "ordinal", title: null,
            sort: ["Year 3", "Year 5", "Year 7", "Year 9"]
        }
    },

    layer: [
        {
            mark: {
                type: "rect", stroke: "#f6f3eb",
                strokeWidth: 4, cornerRadius: 3
            },
            encoding: {
                color: {
                    field: "support",
                    type: "quantitative",
                    title: "Needs additional support (%)",
                    scale: supportColourScale
                },
                tooltip: [
                    { field: "gradeLabel", title: "Year level" },
                    { field: "domain", title: "Subject" },
                    {
                        field: "support",
                        title: "Needs additional support (%)",
                        format: ".1f"
                    }
                ]
            }
        },
        {
            mark: {
                type: "text",
                fontSize: 18,
                fontWeight: "bold"
            },
            encoding: {
                text: { field: "label" },
                color: {
                    condition: {
                        test: "datum.support >= 28",
                        value: "white"
                    },
                    value: "#193a3a"
                }
            }
        }
    ]
});

// CHART 2: proficiency composition.

const chart2 = vl({
    width: 500,
    height: 120,
    data: { values: proficiencyData },
    mark: { type: "bar", height: 35 },

    encoding: {
        y: {
            field: "subject", type: "nominal",
            sort: ["Reading", "Numeracy"], title: null
        },
        x: {
            field: "percentage",
            type: "quantitative",
            stack: "zero",
            title: "Share of reported participants (%)",
            scale: { domain: [0, 100] },
            axis: { labelExpr: "datum.value + '%'" }
        },
        color: {
            field: "category",
            type: "nominal",
            title: null,
            scale: {
                domain: [
                    "Needs additional support", "Developing",
                    "Strong", "Exceeding", "Exempt"
                ],
                range: palette.proficiency
            },
            legend: { columns: 2, labelLimit: 250 }
        },
        order: {
            field: "order",
            type: "quantitative",
            sort: "ascending"
        },
        tooltip: [
            { field: "subject", title: "Subject" },
            { field: "category", title: "Category" },
            {
                field: "percentage",
                title: "Percentage (%)",
                format: ".1f"
            }
        ]
    }
});

// CHART 3: choropleth.

const chart3 = vl({
    width: 500,
    height: 370,

    projection: {
        type: "conicEqualArea",
        parallels: [-18, -36],
        rotate: [-134, 0, 0],
        center: [0, -28]
    },

    params: [
        { name: "map_subject", value: "Reading" }
    ],

    layer: [
        {
            data: { values: mapFeatures },

            transform: [
                {
                    lookup: "properties.STATE_NAME",
                    from: {
                        data: { values: stateData },
                        key: "state",
                        fields: [
                            "reading_support", "numeracy_support",
                            "reading_flag", "numeracy_flag"
                        ]
                    }
                },
                {
                    calculate:
                        "map_subject === 'Reading' ? datum.reading_support : datum.numeracy_support",
                    as: "support"
                },
                {
                    calculate:
                        "isValid(datum.support) ? datum.support : -1",
                    as: "display_support"
                },
                {
                    calculate:
                        "isValid(datum.support) ? format(datum.support, '.1f') + '%' : 'Not reported (low participation)'",
                    as: "support_label"
                },
                {
                    calculate:
                        "map_subject === 'Reading' ? datum.reading_flag : datum.numeracy_flag",
                    as: "reporting_flag"
                }
            ],

            mark: {
                type: "geoshape",
                stroke: "#f6f3eb",
                strokeWidth: 1.2
            },

            encoding: {
                color: {
                    condition: {
                        test: "isValid(datum.support)",
                        field: "display_support",
                        type: "quantitative",
                        title: "Needs additional support (%)",
                        scale: supportColourScale
                    },
                    value: "#cbd2cc"
                },
                tooltip: [
                    {
                        field: "properties.STATE_NAME",
                        title: "State / territory"
                    },
                    {
                        field: "support_label",
                        title: "Needs additional support"
                    },
                    {
                        field: "reporting_flag",
                        title: "Reporting flag"
                    }
                ]
            }
        },
        {
            data: { values: stateData },
            transform: [{ filter: "datum.abbr !== 'ACT'" }],
            mark: {
                type: "text", color: "#193a3a",
                fontWeight: "bold", fontSize: 11
            },
            encoding: {
                longitude: { field: "lon", type: "quantitative" },
                latitude: { field: "lat", type: "quantitative" },
                text: { field: "abbr" }
            }
        }
    ]
});

// CHART 4: proportional-symbol map.

const chart4 = vl({
    width: 500,
    height: 370,

    projection: {
        type: "conicEqualArea",
        parallels: [-18, -36],
        rotate: [-134, 0, 0],
        center: [0, -28]
    },

    params: [
        { name: "symbol_subject", value: "Reading" }
    ],

    layer: [
        {
            data: { values: mapFeatures },
            mark: {
                type: "geoshape",
                fill: "#e1e7e0",
                stroke: "white",
                strokeWidth: 1
            }
        },
        {
            data: { values: stateData },

            transform: [
                {
                    calculate:
                        "symbol_subject === 'Reading' ? datum.reading_participants : datum.numeracy_participants",
                    as: "participants"
                },
                {
                    calculate:
                        "symbol_subject === 'Reading' ? datum.reading_participation : datum.numeracy_participation",
                    as: "participation"
                }
            ],

            mark: {
                type: "circle",
                color: palette.counts,
                opacity: 0.75,
                stroke: "white",
                strokeWidth: 1
            },

            encoding: {
                longitude: { field: "lon", type: "quantitative" },
                latitude: { field: "lat", type: "quantitative" },

                size: {
                    field: "participants",
                    type: "quantitative",
                    title: "NAPLAN participants",
                    scale: { range: [0, 2400], zero: true }
                },

                tooltip: [
                    { field: "state", title: "State / territory" },
                    {
                        field: "participants",
                        title: "Participants",
                        format: ",.0f"
                    },
                    {
                        field: "participation",
                        title: "Participation (%)",
                        format: ".1f"
                    }
                ]
            }
        },
        {
            data: { values: stateData },
            transform: [{ filter: "datum.abbr !== 'ACT'" }],
            mark: {
                type: "text", color: "#193a3a",
                fontWeight: "bold", fontSize: 10, dy: 4
            },
            encoding: {
                longitude: { field: "lon", type: "quantitative" },
                latitude: { field: "lat", type: "quantitative" },
                text: { field: "abbr" }
            }
        }
    ]
});

