function block(year, grade, subject) {
    return FILTER_DATA[year + "-" + grade + "-" + subject];
}

function replaceRows(target, rows) {
    target.splice(0, target.length, ...rows);
}

// ==================================================
// 7. PREPARE DATA FOR THE SELECTED FILTERS
// ==================================================

function prepareCharts(year, grade, subject) {
    for (const spec of [chart3, chart4, chart5, chart7, chart11, chart13]) {
        spec.params.find(p => p.name === "focus_state").value = selectedState;
    }
    // Chart 1: all year levels and both subjects.

    replaceRows(
        nationalData,
        grades.flatMap(g =>
            subjects.map(s => ({
                gradeLabel: "Year " + g,
                domain: s,
                support: block(year, g, s).national[0],
                label: block(year, g, s).national[0].toFixed(1) + "%"
            }))
        )
    );

    // Chart 2: selected year level, both subjects.

    const categories = [
        "Needs additional support",
        "Developing",
        "Strong",
        "Exceeding",
        "Exempt"
    ];

    replaceRows(
        proficiencyData,
        subjects.flatMap(s =>
            categories.map((category, i) => ({
                subject: s,
                category: category,
                percentage: block(year, grade, s).national[i],
                order: i + 1
            }))
        )
    );

    // Charts 3 and 4: update state results.

    for (let i = 0; i < stateData.length; i++) {
        for (const s of subjects) {
            const a = block(year, grade, s).states[i];
            const prefix = s.toLowerCase();

            stateData[i][prefix + "_support"] = a[0];
            stateData[i][prefix + "_participants"] = a[1];
            stateData[i][prefix + "_participation"] = a[2];
            stateData[i][prefix + "_flag"] = a[3];
        }
    }

    // Chart 7: missing achievement stays missing.

    replaceRows(
        stateSupportData,
        stateData.flatMap(d =>
            subjects.map(s => ({
                state: d.state,
                domain: s,
                support: d[s.toLowerCase() + "_support"]
            }))
        ).filter(d => d.support !== null)
    );

    // Chart 8: remoteness.

    replaceRows(
        remotenessData,
        subjects.flatMap(s =>
            remoteNames.map((subgroup, i) => ({
                domain: s,
                subgroup: subgroup,
                support: block(year, grade, s).remote[i]
            }))
        )
    );

    // Chart 9: all year levels.

    replaceRows(
        genderData,
        grades.flatMap(g =>
            subjects.map(s => ({
                grade: "Year " + g,
                domain: s,
                gap: block(year, g, s).gap
            }))
        )
    );

    // Chart 10: parental-education category profiles.

    replaceRows(
        parentData,
        subjects.flatMap(s =>
            parentNames.flatMap((parent, i) =>
                dimensions.map((dimension, axis) => ({
                    domain: s,
                    parent: parent,
                    dimension: dimension,
                    axis: axis,
                    value: block(year, grade, s).parents[i][axis]
                }))
            )
        )
    );

    chart3.params[0].value = subject;
    chart4.params[0].value = subject;
    chart10.params[0].value = subject;

    chart2.title =
        "Year " + grade + " proficiency, Australia, " + year;

    // Chart 11: selected participation and national reference.

    chart11.data.values = stateData.map((d, i) => ({
        state: d.state,
        participation: block(year, grade, subject).states[i][2],
        national: block(year, grade, subject).national[6]
    }));

    // Chart 12: fixed 2023–2026 window, selected year level.

    chart12.data.values = years.flatMap(y =>
        subjects.map(s => ({
            year: y,
            subject: s,
            support: block(y, grade, s).national[0]
        }))
    );

    // Chart 13: same seven jurisdictions in every year.

    chart13.data.values = years.flatMap(y =>
        stateData.flatMap((d, i) =>
            d.abbr === "TAS"
                ? []
                : [{
                    year: y,
                    state: d.state,
                    abbr: d.abbr,
                    support: block(y, grade, subject).states[i][0],
                    flag: block(y, grade, subject).states[i][3]
                }]
        )
    );

    // Chart 14: baseline 2023 versus selected year.
    // Selecting 2023 shows the baseline points only.

    chart14.data.values = [...new Set([2023, year])].flatMap(y => [
        {
            year: y,
            parent: "Year 11 or below",
            proficient: block(y, grade, subject).ends[0]
        },
        {
            year: y,
            parent: "Bachelor or above",
            proficient: block(y, grade, subject).ends[1]
        }
    ]);
}

// ==================================================
// 8. UPDATE CAPTIONS AND ANNOTATIONS
// ==================================================

function updateText(year, grade, subject) {
    const b = block(year, grade, subject);
    const r = block(year, grade, "Reading");
    const n = block(year, grade, "Numeracy");
    const f = value => Number(value).toFixed(1);

    const captions = [
        `${year} · Australia · all year levels · both subjects`,
        `${year} · Australia · Year ${grade} · both subjects`,
        `${year} · Year ${grade} · ${subject}`,
        `${year} · Year ${grade} · ${subject}`,
        "2025 · ABS all-school enrolments · fixed population context",
        "2025 · ABS school sectors · fixed population context",
        `${year} · Year ${grade} · both subjects`,
        `${year} · Australia · Year ${grade} · both subjects`,
        `${year} · Australia · all year levels · both subjects`,
        `${year} · Australia · Year ${grade} · ${subject}`,
        `${year} · Year ${grade} · ${subject}`,
        `2023–2026 · Australia · Year ${grade} · both subjects`,
        `2023–2026 · Year ${grade} · ${subject} · consistent seven-jurisdiction set`,
        year === 2023
            ? `2023 baseline · Year ${grade} · ${subject}`
            : `2023 compared with ${year} · Year ${grade} · ${subject}`
    ];

    const lowest = subjects.map(s => {
        const minimum = Math.min(
            ...grades.map(g => block(year, g, s).national[0])
        );

        const levels = grades
            .filter(g => block(year, g, s).national[0] === minimum)
            .map(g => "Year " + g)
            .join(" and ");

        return s + ": " + levels;
    }).join("; ");

    const supportField = subject.toLowerCase() + "_support";

    const validStates = stateData.filter(
        d => d[supportField] !== null
    );

    const highest = validStates.reduce((a, d) =>
        d[supportField] > a[supportField] ? d : a
    );

    const gap = b.ends[1] - b.ends[0];
    const initial = block(2023, grade, subject).ends;

    const rStrong = r.national[2] + r.national[3];
    const nStrong = n.national[2] + n.national[3];
    const sorted = validStates.slice().sort((a,d) => a[supportField] - d[supportField]);
    const largestPopulation = stateData.reduce((a,d) => d[subject.toLowerCase()+"_participants"] > a[subject.toLowerCase()+"_participants"] ? d : a);
    const firstTrend = subjects.map(s => block(2023,grade,s).national[0]);
    const lastTrend = subjects.map(s => block(2026,grade,s).national[0]);
    const change = d => Math.abs(d) < 0.00005 ? "unchanged" : `${d > 0 ? "up" : "down"} ${f(Math.abs(d))} percentage points`;
    const stateChanges = stateData.flatMap((d,i) => d.abbr === "TAS" ? [] : [{
        state: d.state,
        start: block(2023,grade,subject).states[i][0],
        end: block(2026,grade,subject).states[i][0]
    }]);
    const largestChange = stateChanges.reduce((a,d) =>
        Math.abs(d.end-d.start) > Math.abs(a.end-a.start) ? d : a
    );
    const belowReference = b.states.filter(d => d[2] < b.national[6]).length;
    const notes = [
        `The lowest reported support share occurs in ${lowest}. The differences are between year-level cohorts, not the progress of the same students. Darker cells indicate higher percentages. The heatmap and state map share a fixed 0–40% colour scale; cell labels show the exact values.`,
        `In Year ${grade}, ${f(rStrong)}% are Strong or Exceeding in Reading and ${f(nStrong)}% in Numeracy. Needs additional support accounts for ${f(r.national[0])}% and ${f(n.national[0])}% respectively. Subject standards differ; Developing and Exempt remain separate categories.`,
        `Reported ${subject} support shares range from ${f(sorted[0][supportField])}% in ${sorted[0].state} to ${f(highest[supportField])}% in ${highest.state}. ${year === 2026 ? "Tasmania is grey because achievement is suppressed; it is not zero." : "The fixed colour scale matches the national heatmap and stays the same across selections."} Click a state to follow it.`,
        `${largestPopulation.state} has the largest participant count for this selection (${largestPopulation[subject.toLowerCase()+"_participants"].toLocaleString("en-AU")}). Circle area shows counts, whereas the earlier state map shows support percentages. Participants include assessed, non-attempt and exempt students.`,
        "NSW and Victoria together account for 55.8% of all Australian school enrolments in 2025. Slate state-shape area represents enrolment count; pale outlines show geographic reference only. This wider school population is context, not the selected NAPLAN cohort.",
        "Government schools account for 62.8% of the 4,160,918 enrolments, followed by Catholic (20.0%) and Independent (17.2%) schools. The treemap describes the system's structure, not differences in sector performance.",
        `Across the ${sorted.length} reported jurisdictions, ${subject} support shares span ${f(sorted[0][supportField])}% to ${f(highest[supportField])}%. Each jurisdiction has equal weight. The box covers the middle half; its white line is the median and whiskers show the minimum and maximum. Following a state highlights its point without changing this distribution.`,
        `Reading support is ${f(r.remote[0])}% in major cities and ${f(r.remote[4])}% in very remote areas, a difference of ${f(r.remote[4]-r.remote[0])} percentage points. Compare the two subjects within each row. This association does not establish that remoteness causes the difference.`,
        `In Year ${grade}, the female-minus-male difference in Strong or Exceeding is ${f(r.gap)} percentage points for Reading and ${f(n.gap)} for Numeracy. Right of zero means a higher female share; left means a higher male share. These observed differences are not a statistical significance test.`,
        `For ${subject}, ${f(b.parents[0][0])}% need support in the Year 11-or-below parental-education group, compared with ${f(b.parents[4][0])}% in the Bachelor-or-above group. Each axis is a different category percentage, not time or student movement. Exempt and Not stated are omitted without normalising; click the legend to focus on profiles.`,
        `${belowReference} of eight jurisdictions have participation below the national reference of ${f(b.national[6])}%. The dark tick marks that reference; slate bars show state participation. Coverage matters when interpreting achievement; no causal effect is established.`,
        `From 2023 to 2026, Year ${grade} Reading support moves from ${f(firstTrend[0])}% to ${f(lastTrend[0])}% (${change(lastTrend[0]-firstTrend[0])}); Numeracy moves from ${f(firstTrend[1])}% to ${f(lastTrend[1])}% (${change(lastTrend[1]-firstTrend[1])}). These are different annual cohorts within the series reset in 2023.`,
        `From 2023 to 2026, ${largestChange.state} has the largest absolute change in ${subject} support share among the seven jurisdictions shown: ${f(largestChange.start)}% to ${f(largestChange.end)}% (${change(largestChange.end-largestChange.start)}). Lines show actual percentages rather than ranks. Use the state selector here to highlight one line; the same state stays highlighted in related charts. Tasmania is excluded throughout because its 2026 achievement is not reported. These are different annual cohorts.`,
        year === 2023
            ? `The baseline gap is ${f(gap)} percentage points: ${f(b.ends[0])}% Strong or Exceeding in the Year 11-or-below parental-education group and ${f(b.ends[1])}% in the Bachelor-or-above group. Select a later year for an endpoint comparison.`
            : `The gap is ${f(initial[1]-initial[0])} percentage points in 2023 and ${f(gap)} in ${year}. Endpoint labels show the two groups' actual shares. The comparison describes different cohorts and does not establish a causal effect of parental education.`
    ];

    charts.forEach(([id], i) => {
        const article = document.getElementById(id).closest("article");

        article.querySelector(".chart-subtitle").textContent =
            captions[i];

        article.querySelector(".chart-note").textContent =
            notes[i];

        if (i !== 4 && i !== 5) {
            const context = [0,8].includes(i) ? "all year levels" : `Year ${grade}`;
            article.querySelector(".source").textContent =
                `Source: ACARA NAPLAN national results, 2026 workbook; ${i === 11 || i === 12 ? "2023–2026" : i === 13 && year !== 2023 ? `2023 and ${year}` : year}, ${context}. Values shown to one decimal place.` +
                ([2,3].includes(i) ? " Boundaries: ABS via geoBoundaries, CC BY 4.0; conic equal-area projection, simplified outlines. Original reporting flags remain in tooltips." : "");
        }

    });

    const setText=(id,text)=>{const element=document.getElementById(id);if(element)element.textContent=text;};
    setText("hero-context",`${year} · Year ${grade} · Australia`);
    setText("hero-reading",f(r.national[0]));
    setText("hero-numeracy",f(n.national[0]));
    setText("closing-evidence",`For ${year}, Year ${grade}, ${subject}: ${f(b.national[0])}% nationally needed additional support. Reported jurisdiction shares range from ${f(sorted[0][supportField])}% in ${sorted[0].state} to ${f(highest[supportField])}% in ${highest.state}. The Year 11-or-below and Bachelor-or-above parental-education groups differ by ${f(b.parents[0][0]-b.parents[4][0])} percentage points in their reported support shares.`);

}

