// ==================================================
// 10. RENDER AND UPDATE ALL FOURTEEN CHARTS
// ==================================================

let lastEnrolmentState = null;
let enrolmentReveal = null;
function updateEnrolmentDetail() {
    const panel = document.getElementById("enrolment-detail");
    if (!panel) return;
    const total = enrolmentData.reduce((sum, row) => sum + row.total, 0);
    const row = enrolmentData.find(row => row.state === selectedState);
    const outline = document.getElementById("enrolment-state-outline");
    document.getElementById("enrolment-detail-title").textContent = row ? row.state : "Australia";
    document.getElementById("enrolment-detail-count").textContent = (row ? row.total : total).toLocaleString("en-AU");
    document.getElementById("enrolment-detail-share").textContent = row
        ? `${(row.total / total * 100).toFixed(1)}% of Australia's school enrolments in 2025.`
        : "Click a state shape or use Highlight a state above to reveal its enrolments.";
    document.getElementById("enrolment-outline-wrap").hidden = !row;
    if (row) {
        // Use the actual prepared polygon as an identification silhouette.
        const feature = enrolmentScaledShapes.find(d => d.properties.state === row.state);
        const points = feature.geometry.coordinates[0];
        const xs = points.map(p => p[0]), ys = points.map(p => p[1]);
        const minX = Math.min(...xs), minY = Math.min(...ys);
        const width = Math.max(...xs) - minX, height = Math.max(...ys) - minY;
        const pad = Math.max(width, height) * 0.08;
        outline.setAttribute("viewBox", `${minX-pad} ${minY-pad} ${width+pad*2} ${height+pad*2}`);
        document.getElementById("enrolment-state-path").setAttribute("d", "M" + points.map(p => p.join(",")).join("L") + "Z");
    }
    const reduceMotion = typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (lastEnrolmentState !== null && lastEnrolmentState !== selectedState && !reduceMotion && typeof panel.animate === "function") {
        if (enrolmentReveal) enrolmentReveal.cancel();
        enrolmentReveal = panel.animate(
            [{opacity: 0, transform: "translateY(10px)"}, {opacity: 1, transform: "translateY(0)"}],
            {duration: 280, easing: "ease-out"}
        );
    }
    lastEnrolmentState = selectedState;
}
function updateStateSummary() {
 updateEnrolmentDetail();
 const summary=document.getElementById("state-summary");
 if(!summary)return;
 const participation=document.getElementById("participation-summary");
 document.querySelectorAll("[data-state-focus]").forEach(label=>{
  const id=label.getAttribute("data-state-focus");
  const suppressed=selectedState==="Tasmania"&&document.getElementById("assessment-year").value==="2026";
  label.textContent=id==="jurisdiction-trend"&&selectedState==="Tasmania"?"Tasmania is excluded from this comparison":id==="state-distribution"&&suppressed?"Tasmania: achievement not reported for 2026":selectedState==="All states"?id==="jurisdiction-trend"?"Seven jurisdictions · Tasmania excluded":"Showing all states":"Highlighting "+selectedState;
 });
 if(selectedState==="All states"){
  summary.textContent="Choose a state to compare its support percentage with the national result. All states remain visible.";
  if(participation)participation.textContent="";
  return;
 }
 const year=Number(document.getElementById("assessment-year").value),grade=Number(document.getElementById("year-level").value),subject=document.getElementById("assessment-subject").value;
 const row=stateData.find(d=>d.state===selectedState),prefix=subject.toLowerCase(),value=row[prefix+"_support"],national=block(year,grade,subject).national[0];
 const difference=value===null?null:value-national;
 const comparison=value===null?"Achievement is not reported because participation was too low.":Math.abs(difference)<.05?`The same as the national result to one decimal place (${national.toFixed(1)}%).`:`${Math.abs(difference).toFixed(1)} percentage points ${difference>0?"above":"below"} the national ${national.toFixed(1)}%.`;
 summary.replaceChildren();
 const context=document.createElement("span");context.className="state-context";context.textContent=`${row.state} · ${year} · Year ${grade} · ${subject}`;
 const result=document.createElement("strong");result.textContent=value===null?"Not reported":`${value.toFixed(1)}%`;
 summary.append(context,result,document.createTextNode((value===null?"":"needed additional support. ")+comparison));
 if(participation)participation.textContent=`${row.state} · ${year} · Year ${grade} · ${subject}: ${row[prefix+"_participation"].toFixed(1)}% participation; ${row[prefix+"_participants"].toLocaleString("en-AU")} reported participants.`;
}
async function followState(state) {
    if (rendering || (state !== "All states" && !stateData.some(d=>d.state===state))) return;
    selectedState = state;
    document.getElementById("follow-state").value = state;
    for (const spec of [chart3,chart4,chart5,chart7,chart11,chart13]) spec.params.find(p=>p.name==="focus_state").value=state;
    updateStateSummary();
    const results = await Promise.allSettled(linkedChartIds.map(id => {
        const view=activeViews.get(id);
        return view ? view.signal("focus_state",state).runAsync() : Promise.resolve();
    }));
    for (const result of results) if(result.status==="rejected") console.error("State highlight",result.reason);
}
function connectStateClicks(id,view) {
    if (!linkedChartIds.includes(id)) return;
    view.addEventListener("click", (event,item) => {
        const state=item?.datum?.properties?.STATE_NAME || item?.datum?.properties?.state || item?.datum?.state;
        if(stateData.some(d=>d.state===state))followState(state);
    });
}

const activeViews = new Map();
let rendering = false;
let renderQueued = false;

async function renderAllCharts() {
    if (rendering) {
        renderQueued = true;
        return;
    }

    const status = document.getElementById("page-status");

    if (typeof vegaEmbed !== "function") {
        status.textContent =
            "Vega could not load. Check your internet connection and refresh.";
        return;
    }

    rendering = true;

    // Keep the focused native dropdown enabled. Disabling it while the
    // sticky dock is active can make the browser move to its original position.
    const dock = document.querySelector(".assessment-dock");
    if (dock) dock.setAttribute("aria-busy", "true");

    const year = Number(
        document.getElementById("assessment-year").value
    );

    const grade = Number(
        document.getElementById("year-level").value
    );

    const subject =
        document.getElementById("assessment-subject").value;

    status.textContent = "Updating the assessment results…";

    let failures = 0;

    try {
        prepareCharts(year, grade, subject);
        updateText(year, grade, subject);
        updateStateSummary();

        for (const [id, spec] of charts) {
            try {
                // Render off the page so the visible chart never collapses
                // while Vega prepares its replacement.
                const container = document.getElementById(id);
                const previousView = activeViews.get(id);
                if (typeof container.getBoundingClientRect === "function") {
                    const height = container.getBoundingClientRect().height;
                    if (height > 0) container.style.minHeight = height + "px";
                }
                const replacement = document.createElement("div");
                const result = await vegaEmbed(
                    replacement,
                    JSON.parse(JSON.stringify(spec)),
                    {
                        actions: false,
                        renderer: "svg",
                        mode: id === "sector-treemap"
                            ? "vega"
                            : "vega-lite"
                    }
                );

                container.replaceChildren(replacement);
                if (previousView) previousView.finalize();
                activeViews.set(id, result.view);
                connectStateClicks(id, result.view);
            } catch (error) {
                failures++;

                document.getElementById(id).textContent =
                    "This chart could not load. Check the browser console.";

                console.error(id, error);
            }
        }

        status.textContent = failures
            ? failures + " chart(s) failed. Check the console."
            : "";
    } catch (error) {
        console.error(error);

        status.textContent =
            "The selection could not load. Check that the full JavaScript was copied.";
    } finally {
        if (dock) dock.setAttribute("aria-busy", "false");
        rendering = false;
        if (renderQueued) {
            renderQueued = false;
            await renderAllCharts();
        }
    }
}

// A native select in a sticky toolbar can scroll its original layout position
// into view. Remember the viewport before focus, then undo only automatic
// movement during that interaction. User scrolling cancels the guard.
function prepareAssessmentScrollGuard() {
    const dock = document.querySelector(".assessment-dock");
    if (!dock || typeof requestAnimationFrame !== "function") return;
    let saved = null, frame = 0, until = 0;
    const root = document.documentElement;
    const isControl = target => target && target.closest("select, button") && dock.contains(target);
    function cancel() {
        saved = null;
        if (frame) cancelAnimationFrame(frame);
        frame = 0;
        root.removeAttribute("data-assessment-interaction");
    }
    function tick() {
        frame = 0;
        if (!saved) return;
        if (Math.abs(window.scrollY - saved.y) > 1 || Math.abs(window.scrollX - saved.x) > 1) {
            window.scrollTo({left: saved.x, top: saved.y, behavior: "instant"});
        }
        if (rendering) until = performance.now() + 250;
        if (performance.now() < until) frame = requestAnimationFrame(tick);
        else root.removeAttribute("data-assessment-interaction");
    }
    function schedule() {
        root.setAttribute("data-assessment-interaction", "");
        if (!frame) frame = requestAnimationFrame(tick);
    }
    dock.addEventListener("pointerdown", event => {
        if (!isControl(event.target)) return;
        saved = {x: window.scrollX, y: window.scrollY, control: event.target};
        until = performance.now() + 500;
        schedule();
    }, true);
    dock.addEventListener("keydown", event => {
        if (!isControl(event.target) || !["ArrowUp", "ArrowDown", "Enter", " "].includes(event.key)) return;
        if (!saved || saved.control !== event.target) saved = {x: window.scrollX, y: window.scrollY, control: event.target};
        until = performance.now() + 500;
        schedule();
    }, true);
    dock.addEventListener("change", event => {
        if (!isControl(event.target)) return;
        if (!saved || saved.control !== event.target) saved = {x: window.scrollX, y: window.scrollY, control: event.target};
        until = performance.now() + 500;
        schedule();
    }, true);
    // Never hold the page when the reader deliberately scrolls or navigates.
    window.addEventListener("wheel", cancel, {passive: true});
    window.addEventListener("touchmove", cancel, {passive: true});
    document.addEventListener("pointerdown", event => { if (!dock.contains(event.target)) cancel(); }, true);
    document.addEventListener("keydown", event => {
        if (["Tab", "PageUp", "PageDown", "Home", "End", "Escape"].includes(event.key)) cancel();
    }, true);
}

// The HTML script tag uses defer, so the page is available here.

prepareInterface();
prepareAssessmentScrollGuard();

for (const id of [
    "assessment-year",
    "year-level",
    "assessment-subject"
]) {
    document.getElementById(id).addEventListener(
        "change",
        renderAllCharts
    );
}

document.getElementById("follow-state").addEventListener("change", event => followState(event.target.value));
document.getElementById("reset-filters").addEventListener("click", () => {
    if(rendering) return;
    document.getElementById("assessment-year").value = "2026";
    document.getElementById("year-level").value = "9";
    document.getElementById("assessment-subject").value = "Reading";
    document.getElementById("follow-state").value = "All states";
    selectedState = "All states";
    renderAllCharts();
});
renderAllCharts();

function prepareChapterNavigation(){
 const navigation=document.querySelector(".chapter-nav");
 if(!navigation||typeof IntersectionObserver==="undefined")return;
 const links=[...navigation.querySelectorAll("a")],sections=[...document.querySelectorAll(".story-chapter")],visible=new Set();
 const activate=id=>links.forEach(link=>{if(link.getAttribute("href")==="#"+id)link.setAttribute("aria-current","location");else link.removeAttribute("aria-current");});
 const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting)visible.add(entry.target.id);else visible.delete(entry.target.id);});const current=sections.find(section=>visible.has(section.id));if(current)activate(current.id);},{rootMargin:"-15% 0px -55% 0px",threshold:0});
 sections.forEach(section=>observer.observe(section));
 links.forEach(link=>link.addEventListener("click",()=>activate(link.getAttribute("href").slice(1))));
 activate("national-picture");
}
prepareChapterNavigation();

// Open reference material when an in-page source link points into a closed panel.
function revealReferenceTarget(hash) {
    if (!hash || hash === "#") return;
    const target = document.getElementById(hash.slice(1));
    if (!target) return;
    let element = target;
    while (element) {
        if (element.tagName === "DETAILS") element.open = true;
        element = element.parentElement;
    }
}
document.querySelectorAll('a[href^="#"]').forEach(link => {
    link.addEventListener("click", () => revealReferenceTarget(link.hash));
});
window.addEventListener("hashchange", () => revealReferenceTarget(location.hash));
revealReferenceTarget(location.hash);
